// 브라우저 탭을 강제 종료하면 '나감' 메시지는 안 온다
// → 만료 방식으로 짜야 한다

const 있는사람 = new Map();   // userId → 마지막 신호 시각

socket.on('heartbeat', (u) => 있는사람.set(u.id, Date.now()));

setInterval(() => {
  const 지금 = Date.now();
  for (const [id, t] of 있는사람) {
    if (지금 - t > 30_000) { 있는사람.delete(id); 알림(id, '나감'); }
  }
}, 5_000);

// ❌ 움직임마다 전송 → 사람 10명이면 초당 수백 메시지
// ✅ 20~30ms 로 묶어서 마지막 위치만
let 대기 = null;
onMouseMove((p) => {
  대기 = p;
});
setInterval(() => { if (대기) { send({ type: 'cursor', p: 대기 }); 대기 = null; } }, 30);

// 받는 쪽은 보간(interpolation)으로 부드럽게 — 30ms 간격도 매끄럽게 보인다
